using MediatR;using Microsoft.EntityFrameworkCore;using MSA.OrderService.Domain;using MSA.Repositories.Persistence;
namespace MSA.OrderService.Infrastructure;
public sealed class OrderDbContext(DbContextOptions<OrderDbContext> options,IMediator mediator):MessagingDbContext(options,mediator)
{public DbSet<Order> Orders=>Set<Order>();public DbSet<OrderProductProjection> ProductProjections=>Set<OrderProductProjection>();protected override void OnModelCreating(ModelBuilder b){base.OnModelCreating(b);b.Entity<Order>(e=>{e.ToTable("orders");e.HasKey(x=>x.Id);e.HasIndex(x=>new{x.UserId,x.IdempotencyKey}).IsUnique();e.Property(x=>x.IdempotencyKey).HasMaxLength(100);e.Property(x=>x.Amount).HasPrecision(18,2);e.Property(x=>x.Currency).HasMaxLength(3);e.Property(x=>x.Version).IsConcurrencyToken();e.HasMany(x=>x.Lines).WithOne().HasForeignKey("OrderId");});b.Entity<OrderLine>(e=>{e.ToTable("order_lines");e.HasKey(x=>x.Id);e.Property(x=>x.Sku).HasMaxLength(80);e.Property(x=>x.ProductName).HasMaxLength(200);e.Property(x=>x.UnitPrice).HasPrecision(18,2);});b.Entity<OrderProductProjection>(e=>{e.ToTable("product_projections");e.HasKey(x=>x.ProductId);e.HasIndex(x=>x.Sku).IsUnique();e.Property(x=>x.Price).HasPrecision(18,2);});}}
